begin;
with j as (select * from jsonb_to_recordset($law7d0027$[{"code_id":"GK_RF","article_number":"429.3","version_date":"1994-11-30","article_text":"1. По опционному договору одна сторона на условиях, предусмотренных этим договором, вправе потребовать в установленный договором срок от другой стороны совершения предусмотренных опционным договором действий (в том числе уплатить денежные средства, передать или принять имущество), и при этом, если управомоченная сторона не заявит требование в указанный срок, опционный договор прекращается. Опционным договором может быть предусмотрено, что требование по опционному договору считается заявленным при наступлении определенных таким договором обстоятельств.\n\n2. За право заявить требование по опционному договору сторона уплачивает предусмотренную таким договором денежную сумму, за исключением случаев, если опционным договором, в том числе заключенным между коммерческими организациями, предусмотрена его безвозмездность либо если заключение такого договора обусловлено иным обязательством или иным охраняемым законом интересом, которые вытекают из отношений сторон.\n\n3. При прекращении опционного договора платеж, предусмотренный пунктом 2 настоящей статьи, возврату не подлежит, если иное не предусмотрено опционным договором.\n\n4. Особенности отдельных видов опционных договоров могут быть установлены законом или в установленном им порядке.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.3. Опционный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1a4a72a601c63edef9345fb52f9fcde053362f67aaa1dd7839ba567f122fff87"},{"code_id":"GK_RF","article_number":"429.4","version_date":"1994-11-30","article_text":"1. Договором с исполнением по требованию (абонентским договором) признается договор, предусматривающий внесение одной из сторон (абонентом) определенных, в том числе периодических, платежей или иного предоставления за право требовать от другой стороны (исполнителя) предоставления предусмотренного договором исполнения в затребованных количестве или объеме либо на иных условиях, определяемых абонентом.\n\n2. Абонент обязан вносить платежи или предоставлять иное исполнение по абонентскому договору независимо от того, было ли затребовано им соответствующее исполнение от исполнителя, если иное не предусмотрено законом или договором.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.4. Договор с исполнением по требованию (абонентский договор)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b4f8e6e381fcd401ef71860db0259936e991c3f2280335d03e145b685adf0b2"},{"code_id":"GK_RF","article_number":"43","version_date":"1994-11-30","article_text":"1. Имущество гражданина, признанного безвестно отсутствующим, при необходимости постоянного управления им передается на основании решения суда лицу, которое определяется органом опеки и попечительства и действует на основании договора о доверительном управлении, заключаемого с этим органом.\n\nИз этого имущества выдается содержание гражданам, которых безвестно отсутствующий обязан содержать, и погашается задолженность по другим обязательствам безвестно отсутствующего.\n\n2. Орган опеки и попечительства может и до истечения года со дня получения сведений о месте пребывания отсутствующего гражданина назначить управляющего его имуществом.\n\n3. Последствия признания лица безвестно отсутствующим, не предусмотренные настоящей статьей, определяются законом.","article_title":"Статья 43. Последствия признания гражданина безвестно отсутствующим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3749a6549ef53fcf00a86a22c2380aafa2f75124938e2db4e999398fd42c0a34"},{"code_id":"GK_RF","article_number":"430","version_date":"1994-11-30","article_text":"1. Договором в пользу третьего лица признается договор, в котором стороны установили, что должник обязан произвести исполнение не кредитору, а указанному или не указанному в договоре третьему лицу, имеющему право требовать от должника исполнения обязательства в свою пользу.\n\n2. Если иное не предусмотрено законом, иными правовыми актами или договором, с момента выражения третьим лицом должнику намерения воспользоваться своим правом по договору стороны не могут расторгать или изменять заключенный ими договор без согласия третьего лица.\n\n3. Должник в договоре вправе выдвигать против требования третьего лица возражения, которые он мог бы выдвинуть против кредитора.\n\n4. В случае, когда третье лицо отказалось от права, предоставленного ему по договору, кредитор может воспользоваться этим правом, если это не противоречит закону, иным правовым актам и договору.","article_title":"Статья 430. Договор в пользу третьего лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aebf114492e822fdff4ef88a9b2ac2dd3949667c71077269f0c32b57abb92c85"},{"code_id":"GK_RF","article_number":"431","version_date":"1994-11-30","article_text":"При толковании условий договора судом принимается во внимание буквальное значение содержащихся в нем слов и выражений. Буквальное значение условия договора в случае его неясности устанавливается путем сопоставления с другими условиями и смыслом договора в целом.\n\nЕсли правила, содержащиеся в части первой настоящей статьи, не позволяют определить содержание договора, должна быть выяснена действительная общая воля сторон с учетом цели договора. При этом принимаются во внимание все соответствующие обстоятельства, включая предшествующие договору переговоры и переписку, практику, установившуюся во взаимных отношениях сторон, обычаи, последующее поведение сторон. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 431. Толкование договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cca70f2c0dd6226c61f85b27c5da5b85c92b1c3fb5e9953c4765eaba729b236"},{"code_id":"GK_RF","article_number":"431.1","version_date":"1994-11-30","article_text":"1. Положения настоящего Кодекса о недействительности сделок (параграф 2 главы 9) применяются к договорам, если иное не установлено правилами об отдельных видах договоров и настоящей статьей.\n\n2. Сторона, которая приняла от контрагента исполнение по договору, связанному с осуществлением его сторонами предпринимательской деятельности, и при этом полностью или частично не исполнила свое обязательство, не вправе требовать признания договора недействительным, за исключением случаев признания договора недействительным по основаниям, предусмотренным статьями 173, 178 и 179 настоящего Кодекса, а также если предоставленное другой стороной исполнение связано с заведомо недобросовестными действиями этой стороны.\n\n3. В случае признания недействительным по требованию одной из сторон договора, который является оспоримой сделкой и исполнение которого связано с осуществлением его сторонами предпринимательской деятельности, общие последствия недействительности сделки (статья 167) применяются, если иные последствия недействительности договора не предусмотрены соглашением сторон, заключенным после признания договора недействительным и не затрагивающим интересов третьих лиц, а также не нарушающим публичных интересов.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 431.1. Недействительность договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10922d80d9498a3597b510b2bc0c0e779688931108b777ae266f7443e1018ee4"},{"code_id":"GK_RF","article_number":"431.2","version_date":"1994-11-30","article_text":"1. Сторона, которая при заключении договора либо до или после его заключения дала другой стороне недостоверные заверения об обстоятельствах, имеющих значение для заключения договора, его исполнения или прекращения (в том числе относящихся к предмету договора, полномочиям на его заключение, соответствию договора применимому к нему праву, наличию необходимых лицензий и разрешений, своему финансовому состоянию либо относящихся к третьему лицу), обязана возместить другой стороне по ее требованию убытки, причиненные недостоверностью таких заверений, или уплатить предусмотренную договором неустойку.\n\nПризнание договора незаключенным или недействительным само по себе не препятствует наступлению последствий, предусмотренных абзацем первым настоящего пункта.\n\nПредусмотренная настоящей статьей ответственность наступает, если сторона, предоставившая недостоверные заверения, исходила из того, что другая сторона будет полагаться на них, или имела разумные основания исходить из такого предположения.\n\n2. Сторона, полагавшаяся на недостоверные заверения контрагента, имеющие для нее существенное значение, наряду с требованием о возмещении убытков или взыскании неустойки также вправе отказаться от договора, если иное не предусмотрено соглашением сторон.\n\n3. Сторона, заключившая договор под влиянием обмана или существенного заблуждения, вызванного недостоверными заверениями, данными другой стороной, вправе вместо отказа от договора (пункт 2 настоящей статьи) требовать признания договора недействительным (статьи 179 и 178).\n\n4. Последствия, предусмотренные пунктами 1 и 2 настоящей статьи, применяются к стороне, давшей недостоверные заверения при осуществлении предпринимательской деятельности, а равно и в связи с корпоративным договором либо договором об отчуждении акций или долей в уставном капитале хозяйственного общества, независимо от того, было ли ей известно о недостоверности таких заверений, если иное не предусмотрено соглашением сторон.\n\nВ случаях, предусмотренных абзацем первым настоящего пункта, предполагается, что сторона, предоставившая недостоверные заверения, знала, что другая сторона будет полагаться на такие заверения.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 431.2. Заверения об обстоятельствах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b4e88700c45ff2b5e5d63d1853e0801a9e25fe428020e957b160eed03e7a807"},{"code_id":"GK_RF","article_number":"432","version_date":"1994-11-30","article_text":"1. Договор считается заключенным, если между сторонами, в требуемой в подлежащих случаях форме, достигнуто соглашение по всем существенным условиям договора.\n\nСущественными являются условия о предмете договора, условия, которые названы в законе или иных правовых актах как существенные или необходимые для договоров данного вида, а также все те условия, относительно которых по заявлению одной из сторон должно быть достигнуто соглашение.\n\n2. Договор заключается посредством направления оферты (предложения заключить договор) одной из сторон и ее акцепта (принятия предложения) другой стороной.","article_title":"Статья 432. Основные положения о заключении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9114a673050a5301756f0a18fccad5c7c1c8a70344834d5dc81124e7b28def1"},{"code_id":"GK_RF","article_number":"433","version_date":"1994-11-30","article_text":"1. Договор признается заключенным в момент получения лицом, направившим оферту, ее акцепта.\n\n2. Если в соответствии с законом для заключения договора необходима также передача имущества, договор считается заключенным с момента передачи соответствующего имущества (статья 224).","article_title":"Статья 433. Момент заключения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"771b4ab44bc0d0c55e0e69666e07e5684b6c1c6ece6d83615ebe1a6476874054"},{"code_id":"GK_RF","article_number":"434","version_date":"1994-11-30","article_text":"1. Договор может быть заключен в любой форме, предусмотренной для совершения сделок, если законом для договоров данного вида не установлена определенная форма.\n\nЕсли стороны договорились заключить договор в определенной форме, он считается заключенным после придания ему условленной формы, хотя бы законом для договоров данного вида такая форма не требовалась.","article_title":"Статья 434. Форма договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cd2cc5ba9c0e806aa455e3df133a5c96404a100006ff75a10fcebd127787308"},{"code_id":"GK_RF","article_number":"434.1","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, граждане и юридические лица свободны в проведении переговоров о заключении договора, самостоятельно несут расходы, связанные с их проведением, и не отвечают за то, что соглашение не достигнуто.\n\n2. При вступлении в переговоры о заключении договора, в ходе их проведения и по их завершении стороны обязаны действовать добросовестно, в частности не допускать вступление в переговоры о заключении договора или их продолжение при заведомом отсутствии намерения достичь соглашения с другой стороной. Недобросовестными действиями при проведении переговоров предполагаются:\n\n1) предоставление стороне неполной или недостоверной информации, в том числе умолчание об обстоятельствах, которые в силу характера договора должны быть доведены до сведения другой стороны;\n\n2) внезапное и неоправданное прекращение переговоров о заключении договора при таких обстоятельствах, при которых другая сторона переговоров не могла разумно этого ожидать.\n\n3. Сторона, которая ведет или прерывает переговоры о заключении договора недобросовестно, обязана возместить другой стороне причиненные этим убытки.\n\nУбытками, подлежащими возмещению недобросовестной стороной, признаются расходы, понесенные другой стороной в связи с ведением переговоров о заключении договора, а также в связи с утратой возможности заключить договор с третьим лицом.\n\n4. Если в ходе переговоров о заключении договора сторона получает информацию, которая передается ей другой стороной в качестве конфиденциальной, она обязана не раскрывать эту информацию и не использовать ее ненадлежащим образом для своих целей независимо от того, будет ли заключен договор. При нарушении этой обязанности она должна возместить другой стороне убытки, причиненные в результате раскрытия конфиденциальной информации или использования ее для своих целей.\n\n5. Стороны могут заключить соглашение о порядке ведения переговоров. Такое соглашение может конкретизировать требования к добросовестному ведению переговоров, устанавливать порядок распределения расходов на ведение переговоров и иные подобные права и обязанности. Соглашение о порядке ведения переговоров может устанавливать неустойку за нарушение предусмотренных в нем положений.\n\nУсловия соглашения о порядке ведения переговоров, ограничивающие ответственность за недобросовестные действия сторон соглашения, ничтожны.\n\n6. Предусмотренные пунктами 3 и 4 настоящей статьи положения об обязанности стороны возместить убытки, причиненные другой стороне, не применяются к гражданам, признаваемым потребителями в соответствии с законодательством о защите прав потребителей.\n\n7. Правила настоящей статьи применяются независимо от того, был ли заключен сторонами договор по результатам переговоров.\n\n8. Правила настоящей статьи не исключают применения к отношениям, возникшим при установлении договорных обязательств, правил главы 59 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 434.1. Переговоры о заключении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"589f244a1bf3503c1b32645f5d3820ce23ca9765ee0a386d8abb50cdf3014c4c"},{"code_id":"GK_RF","article_number":"435","version_date":"1994-11-30","article_text":"1. Офертой признается адресованное одному или нескольким конкретным лицам предложение, которое достаточно определенно и выражает намерение лица, сделавшего предложение, считать себя заключившим договор с адресатом, которым будет принято предложение.\n\nОферта должна содержать существенные условия договора.\n\n2. Оферта связывает направившее ее лицо с момента ее получения адресатом.\n\nЕсли извещение об отзыве оферты поступило ранее или одновременно с самой офертой, оферта считается не полученной.","article_title":"Статья 435. Оферта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"892aab062a0092bf12c85468537283b7718e473193e3239e975462d19f29da1f"},{"code_id":"GK_RF","article_number":"436","version_date":"1994-11-30","article_text":"Полученная адресатом оферта не может быть отозвана в течение срока, установленного для ее акцепта, если иное не оговорено в самой оферте либо не вытекает из существа предложения или обстановки, в которой оно было сделано.","article_title":"Статья 436. Безотзывность оферты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b812c5e2e8b2dd82fe3152d73cd54f579a9ed29f7132a48dc936fdc1f41fb99e"},{"code_id":"GK_RF","article_number":"437","version_date":"1994-11-30","article_text":"1. Реклама и иные предложения, адресованные неопределенному кругу лиц, рассматриваются как приглашение делать оферты, если иное прямо не указано в предложении.\n\n2. Содержащее все существенные условия договора предложение, из которого усматривается воля лица, делающего предложение, заключить договор на указанных в предложении условиях с любым, кто отзовется, признается офертой (публичная оферта).","article_title":"Статья 437. Приглашение делать оферты. Публичная оферта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd12bfc6c8d4983179a54327584162ea19b7e447174f02b1e98e3674e6e13854"},{"code_id":"GK_RF","article_number":"438","version_date":"1994-11-30","article_text":"1. Акцептом признается ответ лица, которому адресована оферта, о ее принятии.\n\nАкцепт должен быть полным и безоговорочным.","article_title":"Статья 438. Акцепт","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f62848256f970139a396abf78d3d3bd444365897a06ea281478d8f085aa1006b"},{"code_id":"GK_RF","article_number":"439","version_date":"1994-11-30","article_text":"Если извещение об отзыве акцепта поступило лицу, направившему оферту, ранее акцепта или одновременно с ним, акцепт считается не полученным.","article_title":"Статья 439. Отзыв акцепта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03d0fe18021045598fc2e68f009bb98c5220c0f61ce97a1e0c19259c5de51542"},{"code_id":"GK_RF","article_number":"44","version_date":"1994-11-30","article_text":"В случае явки или обнаружения места пребывания гражданина, признанного безвестно отсутствующим, суд отменяет решение о признании его безвестно отсутствующим. На основании решения суда отменяется управление имуществом этого гражданина.","article_title":"Статья 44. Отмена решения о признании гражданина безвестно отсутствующим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fc1112b5ca644c9798e0cbefc3025824a0e1623d0d13c8ae756eb8b64a3fbf6b"},{"code_id":"GK_RF","article_number":"440","version_date":"1994-11-30","article_text":"Когда в оферте определен срок для акцепта, договор считается заключенным, если акцепт получен лицом, направившим оферту, в пределах указанного в ней срока.","article_title":"Статья 440. Заключение договора на основании оферты, определяющей срок для акцепта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c745efb2c4602874f44068df245835404dc87eb69f3ee1168fe981daea9b3302"},{"code_id":"GK_RF","article_number":"441","version_date":"1994-11-30","article_text":"1. Когда в письменной оферте не определен срок для акцепта, договор считается заключенным, если акцепт получен лицом, направившим оферту, до окончания срока, установленного законом или иными правовыми актами, а если такой срок не установлен, - в течение нормально необходимого для этого времени.\n\n2. Когда оферта сделана устно без указания срока для акцепта, договор считается заключенным, если другая сторона немедленно заявила о ее акцепте.","article_title":"Статья 441. Заключение договора на основании оферты, не определяющей срок для акцепта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f4538d51d27b89e531c7ded2b35a39e0c848e70474f962fa17a0a46f1149eea"},{"code_id":"GK_RF","article_number":"442","version_date":"1994-11-30","article_text":"В случаях, когда своевременно направленное извещение об акцепте получено с опозданием, акцепт не считается опоздавшим, если сторона, направившая оферту, немедленно не уведомит другую сторону о получении акцепта с опозданием.\n\nЕсли сторона, направившая оферту, немедленно сообщит другой стороне о принятии ее акцепта, полученного с опозданием, договор считается заключенным.","article_title":"Статья 442. Акцепт, полученный с опозданием","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d2b2b01b7fb72bbb3cf44eeaa6792ae621149bc1bcdf0611790072bf5ec4326"},{"code_id":"GK_RF","article_number":"443","version_date":"1994-11-30","article_text":"Ответ о согласии заключить договор на иных условиях, чем предложено в оферте, не является акцептом.\n\nТакой ответ признается отказом от акцепта и в то же время новой офертой.","article_title":"Статья 443. Акцепт на иных условиях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f8d26440b26a66bb431e8287dda7f9a6cdc029f3ec6948674efc35bc1976069"},{"code_id":"GK_RF","article_number":"444","version_date":"1994-11-30","article_text":"Если в договоре не указано место его заключения, договор признается заключенным в месте жительства гражданина или месте нахождения юридического лица, направившего оферту.","article_title":"Статья 444. Место заключения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24ec7bd027c221d9da96c9aa4aef7918d1d740a1c947c148532f80e8355b3825"},{"code_id":"GK_RF","article_number":"445","version_date":"1994-11-30","article_text":"1. В случаях, когда в соответствии с настоящим Кодексом или иными законами для стороны, которой направлена оферта (проект договора), заключение договора обязательно, эта сторона должна направить другой стороне извещение об акцепте, либо об отказе от акцепта, либо об акцепте оферты на иных условиях (протокол разногласий к проекту договора) в течение тридцати дней со дня получения оферты.\n\nСторона, направившая оферту и получившая от стороны, для которой заключение договора обязательно, извещение о ее акцепте на иных условиях (протокол разногласий к проекту договора), вправе передать разногласия, возникшие при заключении договора, на рассмотрение суда в течение тридцати дней со дня получения такого извещения либо истечения срока для акцепта.\n\n2. В случаях, когда в соответствии с настоящим Кодексом или иными законами заключение договора обязательно для стороны, направившей оферту (проект договора), и ей в течение тридцати дней будет направлен протокол разногласий к проекту договора, эта сторона обязана в течение тридцати дней со дня получения протокола разногласий известить другую сторону о принятии договора в ее редакции либо об отклонении протокола разногласий.\n\nПри отклонении протокола разногласий либо неполучении извещения о результатах его рассмотрения в указанный срок сторона, направившая протокол разногласий, вправе передать разногласия, возникшие при заключении договора, на рассмотрение суда.\n\n3. Правила о сроках, предусмотренные пунктами 1 и 2 настоящей статьи, применяются, если другие сроки не установлены законом, иными правовыми актами или не согласованы сторонами.\n\nСторона, необоснованно уклоняющаяся от заключения договора, должна возместить другой стороне причиненные этим убытки.","article_title":"Статья 445. Заключение договора в обязательном порядке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c1b054e895b006c7009acb4b42198e287393e30f1fb3ad0b952790a84f16e389"},{"code_id":"GK_RF","article_number":"447","version_date":"1994-11-30","article_text":"1. Договор, если иное не вытекает из его существа, может быть заключен путем проведения торгов. Договор заключается с лицом, выигравшим торги.\n\nВыигравшим торги на аукционе признается лицо, предложившее наиболее высокую цену, а по конкурсу - лицо, которое по заключению конкурсной комиссии, заранее назначенной организатором торгов, предложило лучшие условия.\n\nФорма торгов определяется собственником продаваемой вещи или обладателем реализуемого имущественного права, если иное не предусмотрено законом.\n\nК организованным торгам правила, предусмотренные статьями 448 и 449 настоящего Кодекса, не применяются, если иное не установлено законом.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 447. Заключение договора на торгах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a1a15c17566a4608dcd7d4741e4f54cea74c351af2d793b5e66cd6a56313cc8"},{"code_id":"GK_RF","article_number":"448","version_date":"1994-11-30","article_text":"1. Аукционы и конкурсы могут быть открытыми и закрытыми. В открытом аукционе и открытом конкурсе может участвовать любое лицо. В закрытом аукционе и закрытом конкурсе участвуют только лица, специально приглашенные для этой цели.\n\n2. Если иное не предусмотрено законом, извещение о проведении торгов должно быть опубликовано организатором не позднее чем за тридцать дней до их проведения. Извещение должно содержать сведения о времени, месте и форме торгов, об их предмете, о существующих обременениях продаваемого имущества и о порядке проведения торгов, в том числе об оформлении участия в торгах, определении лица, выигравшего торги, а также сведения о начальной цене.\n\n3. Условия договора, заключаемого по результатам торгов, определяются организатором торгов и должны быть указаны в извещении о проведении торгов.\n\n4. Если иное не предусмотрено в законе или в извещении о проведении торгов, организатор открытых торгов, опубликовавший извещение, вправе отказаться от проведения аукциона в любое время, но не позднее чем за три дня до наступления даты его проведения, а от проведения конкурса - не позднее чем за тридцать дней до проведения конкурса.\n\nВ случае, если организатор открытых торгов отказался от их проведения с нарушением указанных сроков, он обязан возместить участникам понесенный ими реальный ущерб.\n\nОрганизатор закрытого аукциона или закрытого конкурса обязан возместить приглашенным им участникам реальный ущерб независимо от того, в какой именно срок после направления извещения последовал отказ от проведения торгов.\n\n5. Участники торгов вносят задаток в размере, в сроки и в порядке, которые указаны в извещении о проведении торгов. Если торги не состоялись, задаток подлежит возврату. Задаток возвращается также лицам, которые участвовали в торгах, но не выиграли их.\n\nПри заключении договора с лицом, выигравшим торги, сумма внесенного им задатка засчитывается в счет исполнения обязательств по заключенному договору.\n\nЕсли иное не установлено законом, обязательства организатора и участников торгов по заключению договора по результатам торгов могут обеспечиваться независимой гарантией.\n\n6. Если иное не установлено законом, лицо, выигравшее торги, и организатор торгов подписывают в день проведения аукциона или конкурса протокол о результатах торгов, который имеет силу договора.\n\nЛицо, уклонившееся от подписания протокола, обязано возместить причиненные этим убытки в части, превышающей размер предоставленного обеспечения.\n\nЕсли в соответствии с законом заключение договора возможно только путем проведения торгов, при уклонении организатора торгов от подписания протокола победитель торгов вправе обратиться в суд с требованием о понуждении заключить договор, а также о возмещении убытков, вызванных уклонением от его заключения.\n\n1) по основаниям, установленным законом;\n\n2) в связи с изменением размера процентов за пользование займом при изменении ключевой ставки Банка России (соразмерно такому изменению), если на торгах заключался договор займа (кредита);\n\n3) по иным основаниям, если изменение договора не повлияет на его условия, имевшие существенное значение для определения цены на торгах.\n\n(Пункт в редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 448. Организация и порядок проведения торгов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c989d036ceaf595178ba2862471b056ec203217e0d08b3b9aa4cad4ef25c2c4"},{"code_id":"GK_RF","article_number":"449","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n1. Торги, проведенные с нарушением правил, установленных законом, могут быть признаны судом недействительными по иску заинтересованного лица в течение одного года со дня проведения торгов.\n\nТорги могут быть признаны недействительными в случае, если:\n\nкто-либо необоснованно был отстранен от участия в торгах;\n\nна торгах неосновательно была не принята высшая предложенная цена;\n\nпродажа была произведена ранее указанного в извещении срока;\n\nбыли допущены иные существенные нарушения порядка проведения торгов, повлекшие неправильное определение цены продажи;\n\nбыли допущены иные нарушения правил, установленных законом.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 449. Основания и последствия признания торгов недействительными","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8fd798e54ede29da542f910df00db68f7e30ef231215837be6087dd9f32318d0"},{"code_id":"GK_RF","article_number":"449.1","version_date":"1994-11-30","article_text":"Извещение должно содержать наряду со сведениями, указанными в пункте 2 статьи 448 настоящего Кодекса, указание на собственника (правообладателя) имущества.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 449.1. Публичные торги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"df8078e72b34cac28c28b62189cb106ac531df531b41bfe92f6d54a1fd3b0750"},{"code_id":"GK_RF","article_number":"45","version_date":"1994-11-30","article_text":"1. Гражданин может быть объявлен судом умершим, если в месте его жительства нет сведений о месте его пребывания в течение пяти лет, а если он пропал без вести при обстоятельствах, угрожавших смертью или дающих основание предполагать его гибель от определенного несчастного случая, - в течение шести месяцев.\n\n2. Военнослужащий или иной гражданин, пропавший без вести в связи с военными действиями, может быть объявлен судом умершим не ранее чем по истечении двух лет со дня окончания военных действий.","article_title":"Статья 45. Объявление гражданина умершим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4279c6af9afe2f66edf6807c7ca9d3593a64d1360f149c9f7764a379adea831b"},{"code_id":"GK_RF","article_number":"450","version_date":"1994-11-30","article_text":"1. Изменение и расторжение договора возможны по соглашению сторон, если иное не предусмотрено настоящим Кодексом, другими законами или договором.\n\nМногосторонним договором, исполнение которого связано с осуществлением всеми его сторонами предпринимательской деятельности, может быть предусмотрена возможность изменения или расторжения такого договора по соглашению как всех, так и большинства лиц, участвующих в указанном договоре, если иное не установлено законом. В указанном в настоящем абзаце договоре может быть предусмотрен порядок определения такого большинства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\n2. По требованию одной из сторон договор может быть изменен или расторгнут по решению суда только:\n\n1) при существенном нарушении договора другой стороной;\n\n2) в иных случаях, предусмотренных настоящим Кодексом, другими законами или договором.\n\nСущественным признается нарушение договора одной из сторон, которое влечет для другой стороны такой ущерб, что она в значительной степени лишается того, на что была вправе рассчитывать при заключении договора.","article_title":"Статья 450. Основания изменения и расторжения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"228ac3bded2caf98ddd961cc63e0055280f2663b30a1b5f1e79c288d5c83d4c9"},{"code_id":"GK_RF","article_number":"450.1","version_date":"1994-11-30","article_text":"1. Предоставленное настоящим Кодексом, другими законами, иными правовыми актами или договором право на односторонний отказ от договора (исполнения договора) (статья 310) может быть осуществлено управомоченной стороной путем уведомления другой стороны об отказе от договора (исполнения договора). Договор прекращается с момента получения данного уведомления, если иное не предусмотрено настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n2. В случае одностороннего отказа от договора (исполнения договора) полностью или частично, если такой отказ допускается, договор считается расторгнутым или измененным.\n\n3. В случае отсутствия у одной из сторон договора лицензии на осуществление деятельности или членства в саморегулируемой организации, необходимых для исполнения обязательства по договору, другая сторона вправе отказаться от договора (исполнения договора) и потребовать возмещения убытков.\n\n4. Сторона, которой настоящим Кодексом, другими законами, иными правовыми актами или договором предоставлено право на отказ от договора (исполнения договора), должна при осуществлении этого права действовать добросовестно и разумно в пределах, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n5. В случаях, если при наличии оснований для отказа от договора (исполнения договора) сторона, имеющая право на такой отказ, подтверждает действие договора, в том числе путем принятия от другой стороны предложенного последней исполнения обязательства, последующий отказ по тем же основаниям не допускается.\n\n6. Если иное не предусмотрено настоящим Кодексом, другими законами, иными правовыми актами или договором, в случаях, когда сторона, осуществляющая предпринимательскую деятельность, при наступлении обстоятельств, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором и служащих основанием для осуществления определенного права по договору, заявляет отказ от осуществления этого права, в последующем осуществление этого права по тем же основаниям не допускается, за исключением случаев, когда аналогичные обстоятельства наступили вновь.\n\n7. В случаях, установленных настоящим Кодексом, другими законами, иными правовыми актами или договором, правила пункта 6 настоящей статьи применяются при неосуществлении определенного права в срок, предусмотренный настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 450.1. Отказ от договора (исполнения договора) или от осуществления прав по договору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"740a4dee8223b33cf83f1d1290652efe1fddf3f2388ab899b07c5cbeee4d2483"},{"code_id":"GK_RF","article_number":"451","version_date":"1994-11-30","article_text":"1. Существенное изменение обстоятельств, из которых стороны исходили при заключении договора, является основанием для его изменения или расторжения, если иное не предусмотрено договором или не вытекает из его существа.\n\nИзменение обстоятельств признается существенным, когда они изменились настолько, что, если бы стороны могли это разумно предвидеть, договор вообще не был бы ими заключен или был бы заключен на значительно отличающихся условиях.\n\n2. Если стороны не достигли соглашения о приведении договора в соответствие с существенно изменившимися обстоятельствами или о его расторжении, договор может быть расторгнут, а по основаниям, предусмотренным пунктом 4 настоящей статьи, изменен судом по требованию заинтересованной стороны при наличии одновременно следующих условий:\n\n1) в момент заключения договора стороны исходили из того, что такого изменения обстоятельств не произойдет;\n\n2) изменение обстоятельств вызвано причинами, которые заинтересованная сторона не могла преодолеть после их возникновения при той степени заботливости и осмотрительности, какая от нее требовалась по характеру договора и условиям оборота;\n\n3) исполнение договора без изменения его условий настолько нарушило\n\nбы соответствующее договору соотношение имущественных интересов сторон и повлекло бы для заинтересованной стороны такой ущерб, что она в значительной степени лишилась бы того, на что была вправе рассчитывать при заключении договора;4) из обычаев или существа договора не вытекает, что риск изменения обстоятельств несет заинтересованная сторона. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)3. При расторжении договора вследствие существенно изменившихся обстоятельств суд по требованию любой из сторон определяет последствия расторжения договора, исходя из необходимости справедливого распределения между сторонами расходов, понесенных ими в связи с исполнением этого договора.4. Изменение договора в связи с существенным изменением обстоятельств допускается по решению суда в исключительных случаях, когда расторжение договора противоречит общественным интересам либо повлечет для сторон ущерб, значительно превышающий затраты, необходимые для исполнения договора на измененных судом условиях.Статья 452. Порядок изменения и расторжения договора1. Соглашение об изменении или о расторжении договора совершается в той же форме, что и договор, если из закона, иных правовых актов, договора или обычаев не вытекает иное. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)2. Требование об изменении или о расторжении договора может быть заявлено стороной в суд только после получения отказа другой стороны на предложение изменить или расторгнуть договор либо неполучения ответа в срок, указанный в предложении или установленный законом либо договором, а при его отсутствии - в тридцатидневный срок.Статья 453. Последствия изменения и расторжения договора1. При изменении договора обязательства сторон сохраняются в измененном виде.2. При расторжении договора обязательства сторон прекращаются, если иное не предусмотрено законом, договором или не вытекает из существа обязательства. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)3. В случае изменения или расторжения договора обязательства считаются измененными или прекращенными с момента заключения соглашения сторон об изменении или о расторжении договора, если иное не вытекает из соглашения.В случае изменения или расторжения договора в судебном порядке обязательства считаются измененными или прекращенными с момента вступления в законную силу решения суда об изменении или о расторжении договора, если этим решением не предусмотрена дата, с которой обязательства считаются соответственно измененными или прекращенными. Такая дата определяется судом исходя из существа договора и (или) характера правовых последствий его изменения, но не может быть ранее даты наступления обстоятельств, послуживших основанием для изменения или расторжения договора.(Пункт в редакции  Федерального закона от 24.07.2023 № 347-ФЗ)4. Стороны не вправе требовать возвращения того, что было исполнено ими по обязательству до момента изменения или расторжения договора, если иное не установлено законом или соглашением сторон.В случае, когда до расторжения или изменения договора одна из сторон, получив от другой стороны исполнение обязательства по договору, не исполнила свое обязательство либо предоставила другой стороне неравноценное исполнение, к отношениям сторон применяются правила об обязательствах вследствие неосновательного обогащения (глава 60), если иное не предусмотрено законом или договором либо не вытекает из существа обязательства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)5. Если основанием для изменения или расторжения договора послужило существенное нарушение договора одной из сторон, другая сторона вправе требовать возмещения убытков, причиненных изменением или расторжением договора.Президент Российской Федерации                               Б.ЕльцинМосква, Кремль30 ноября 1994 года№ 51-ФЗ\n\nбы соответствующее договору соотношение имущественных интересов сторон и повлекло бы для заинтересованной стороны такой ущерб, что она в значительной степени лишилась бы того, на что была вправе рассчитывать при заключении договора;\n\n4) из обычаев или существа договора не вытекает, что риск изменения обстоятельств несет заинтересованная сторона. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n3. При расторжении договора вследствие существенно изменившихся обстоятельств суд по требованию любой из сторон определяет последствия расторжения договора, исходя из необходимости справедливого распределения между сторонами расходов, понесенных ими в связи с исполнением этого договора.\n\n4. Изменение договора в связи с существенным изменением обстоятельств допускается по решению суда в исключительных случаях, когда расторжение договора противоречит общественным интересам либо повлечет для сторон ущерб, значительно превышающий затраты, необходимые для исполнения договора на измененных судом условиях.","article_title":"Статья 451. Изменение и расторжение договора в связи с существенным изменением обстоятельств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a86a50c392c56db3cb7b29ec71c7e482817c61f41b9219b4e08e6fc72628ed2a"},{"code_id":"GK_RF","article_number":"453","version_date":"1994-11-30","article_text":"1. При изменении договора обязательства сторон сохраняются в измененном виде.\n\nВ случае изменения или расторжения договора в судебном порядке обязательства считаются измененными или прекращенными с момента вступления в законную силу решения суда об изменении или о расторжении договора, если этим решением не предусмотрена дата, с которой обязательства считаются соответственно измененными или прекращенными. Такая дата определяется судом исходя из существа договора и (или) характера правовых последствий его изменения, но не может быть ранее даты наступления обстоятельств, послуживших основанием для изменения или расторжения договора.\n\n(Пункт в редакции  Федерального закона от 24.07.2023 № 347-ФЗ)\n\nВ случае, когда до расторжения или изменения договора одна из сторон, получив от другой стороны исполнение обязательства по договору, не исполнила свое обязательство либо предоставила другой стороне неравноценное исполнение, к отношениям сторон применяются правила об обязательствах вследствие неосновательного обогащения (глава 60), если иное не предусмотрено законом или договором либо не вытекает из существа обязательства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\nПрезидент Российской Федерации                               Б.Ельцин\n\nМосква, Кремль\n\n30 ноября 1994 года","article_title":"Статья 453. Последствия изменения и расторжения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"929a50b263ce7f19469993b5c587bc1045b28f420357ecd6b15b6d02cd94fe6d"},{"code_id":"GK_RF","article_number":"46","version_date":"1994-11-30","article_text":"1. В случае явки или обнаружения места пребывания гражданина, объявленного умершим, суд отменяет решение об объявлении его умершим.\n\n2. Независимо от времени своей явки гражданин может потребовать от любого лица возврата сохранившегося имущества, которое безвозмездно перешло к этому лицу после объявления гражданина умершим, за исключением случаев, предусмотренных пунктом 3 статьи 302 настоящего Кодекса.\n\nЛица, к которым имущество гражданина, объявленного умершим, перешло по возмездным сделкам, обязаны возвратить ему это имущество, если доказано, что, приобретая имущество, они знали, что гражданин, объявленный умершим, находится в живых. При невозможности возврата такого имущества в натуре возмещается его стоимость.","article_title":"Статья 46. Последствия явки гражданина, объявленного умершим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79f6a83d14ee2d585ce985ede04307fb613bf1ae8dad01d5570c8c453ead42f3"},{"code_id":"GK_RF","article_number":"47","version_date":"1994-11-30","article_text":"1. Государственной регистрации подлежат следующие акты гражданского состояния:\n\n1) рождение;\n\n2) заключение брака;\n\n3) расторжение брака;\n\n4) усыновление (удочерение);\n\n5) установление отцовства;\n\n6) перемена имени;\n\n7) смерть гражданина.\n\nПри наличии спора между заинтересованными лицами либо отказе органов, осуществляющих государственную регистрацию актов гражданского состояния, в исправлении или изменении записи спор разрешается судом. (В редакции  Федерального закона от 27.01.2023 № 3-ФЗ)\n\nАннулирование и восстановление записей актов гражданского состояния производятся органами, осуществляющими государственную регистрацию актов гражданского состояния, на основании решения суда. (В редакции  Федерального закона от 27.01.2023 № 3-ФЗ)","article_title":"Статья 47. Регистрация актов гражданского состояния","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d01062ff164ed2081765d45fa8d89cfd5cc632994565e28174a4457ab42d56a9"},{"code_id":"GK_RF","article_number":"48","version_date":"1994-11-30","article_text":"1. Юридическим лицом признается организация, которая имеет обособленное имущество и отвечает им по своим обязательствам, может от своего имени приобретать и осуществлять гражданские права и нести гражданские обязанности, быть истцом и ответчиком в суде.\n\n2. Юридическое лицо должно быть зарегистрировано в едином государственном реестре юридических лиц в одной из организационно-правовых форм, предусмотренных настоящим Кодексом.\n\n3. К юридическим лицам, на имущество которых их учредители имеют вещные права, относятся государственные и муниципальные унитарные предприятия, а также учреждения.\n\nК юридическим лицам, в отношении которых их участники имеют корпоративные права, относятся корпоративные организации (статья 651).\n\n4. Правовое положение Центрального банка Российской Федерации (Банка России) определяется Конституцией Российской Федерации и законом о Центральном банке Российской Федерации.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 48. Понятие юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69a1257288f745dd0b0dd0c07c1d52cfa739722d5e3e59fc6b0e307a043792be"},{"code_id":"GK_RF","article_number":"49","version_date":"1994-11-30","article_text":"Коммерческие организации, за исключением унитарных предприятий и иных видов организаций, предусмотренных законом, могут иметь гражданские права и нести гражданские обязанности, необходимые для осуществления любых видов деятельности, не запрещенных законом.\n\nВ случаях, предусмотренных законом, юридическое лицо может заниматься отдельными видами деятельности только на основании специального разрешения (лицензии), членства в саморегулируемой организации или выданного саморегулируемой организацией свидетельства о допуске к определенному виду работ.  (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nПраво юридического лица осуществлять деятельность, для занятия которой необходимо получение специального разрешения (лицензии), членство в саморегулируемой организации или получение свидетельства саморегулируемой организации о допуске к определенному виду работ, возникает с момента получения такого разрешения (лицензии) или в указанный в нем срок либо с момента вступления юридического лица в саморегулируемую организацию или выдачи саморегулируемой организацией свидетельства о допуске к определенному виду работ и прекращается при прекращении действия разрешения (лицензии), членства в саморегулируемой организации или выданного саморегулируемой организацией свидетельства о допуске к определенному виду работ.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 49. Правоспособность юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a392d152031eab7ab9a5a17e61590143189fc7042080c80d9166f448d6be60cb"},{"code_id":"GK_RF","article_number":"5","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 5. Обычаи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b39a6ec70ed38789456fd9c819ea98f0d73a459b54a9e5f1ee0ba2995bc18fef"},{"code_id":"GK_RF","article_number":"50","version_date":"1994-11-30","article_text":"1. Юридическими лицами могут быть организации, преследующие извлечение прибыли в качестве основной цели своей деятельности (коммерческие организации) либо не имеющие извлечение прибыли в качестве такой цели и не распределяющие полученную прибыль между участниками (некоммерческие организации).\n\n1) потребительских кооперативов, к которым относятся в том числе жилищные, жилищно-строительные и гаражные кооперативы, общества взаимного страхования, кредитные кооперативы, фонды проката, сельскохозяйственные потребительские кооперативы; (В редакции Федерального закона от 29.07.2017 № 217-ФЗ)\n\n2) общественных организаций, к которым относятся в том числе политические партии и созданные в качестве юридических лиц профессиональные союзы (профсоюзные организации), органы общественной самодеятельности, территориальные общественные самоуправления; (В редакции Федерального закона от 23.05.2015 № 133-ФЗ)\n\n21) общественных движений; (Дополнение подпунктом - Федеральный закон от 23.05.2015 № 133-ФЗ)\n\n3) ассоциаций (союзов), к которым относятся в том числе некоммерческие партнерства, саморегулируемые организации, объединения работодателей, объединения профессиональных союзов, кооперативов и общественных организаций, торгово-промышленные палаты; (В редакции федеральных законов от 13.07.2015 № 268-ФЗ; от 07.02.2017 № 12-ФЗ)\n\n4) товариществ собственников недвижимости, к которым относятся в том числе товарищества собственников жилья, садоводческие или огороднические некоммерческие товарищества; (В редакции Федерального закона от 29.07.2017 № 217-ФЗ)\n\n5) казачьих обществ, внесенных в государственный реестр казачьих обществ в Российской Федерации;\n\n6) общин коренных малочисленных народов Российской Федерации;\n\n7) общественно полезных фондов, к которым относятся в том числе общественные и благотворительные фонды, и личных фондов; (В редакции Федерального закона от 01.07.2021 № 287-ФЗ)\n\n8) учреждений, к которым относятся государственные учреждения (в том числе государственные академии наук), муниципальные учреждения и частные (в том числе общественные) учреждения;\n\n9) автономных некоммерческих организаций;\n\n10) религиозных организаций;\n\n11) публично-правовых компаний;\n\n12) адвокатских палат; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 268-ФЗ)\n\n13) адвокатских образований (являющихся юридическими лицами); (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 268-ФЗ)\n\n14) государственных корпораций; (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 236-ФЗ)\n\n15) нотариальных палат. (Дополнение подпунктом - Федеральный закон от 07.02.2017 № 12-ФЗ)\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 50. Коммерческие и некоммерческие организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"80c4be2920f4ce389e7c52644123c6437389490a7d16480932196e7c4096b0bf"},{"code_id":"GK_RF","article_number":"50.1","version_date":"1994-11-30","article_text":"1. Юридическое лицо может быть создано на основании решения учредителя (учредителей) об учреждении юридического лица.\n\n2. В случае учреждения юридического лица одним лицом решение о его учреждении принимается учредителем единолично.\n\nВ случае учреждения юридического лица двумя и более учредителями указанное решение принимается всеми учредителями единогласно.\n\nВ решении об учреждении корпоративного юридического лица (статья 651) указываются также сведения о результатах голосования учредителей по вопросам учреждения юридического лица, о порядке совместной деятельности учредителей по созданию юридического лица.\n\nВ решении об учреждении юридического лица указываются также иные сведения, предусмотренные законом.\n\nПосле смерти гражданина нотариус, ведущий наследственное дело, направляет в уполномоченный государственный орган заявление о государственной регистрации наследственного фонда с указанием имени или наименования лица (лиц), осуществляющего полномочия единоличного исполнительного органа фонда.\n\n(Дополнение пунктом - Федеральный закон от 29.07.2017 № 259-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 50.1. Решение об учреждении юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd0c45a77e065451fe988a4a82b1a8f5ad53866d183597424903f68e7673aa3f"},{"code_id":"GK_RF","article_number":"51","version_date":"1994-11-30","article_text":"1. Юридическое лицо подлежит государственной регистрации в уполномоченном государственном органе в порядке, предусмотренном законом о государственной регистрации юридических лиц.\n\n2. Данные государственной регистрации включаются в единый государственный реестр юридических лиц, открытый для всеобщего ознакомления.\n\nЛицо, добросовестно полагающееся на данные единого государственного реестра юридических лиц, вправе исходить из того, что они соответствуют действительным обстоятельствам. Юридическое лицо не вправе в отношениях с лицом, полагавшимся на данные единого государственного реестра юридических лиц, ссылаться на данные, не включенные в указанный реестр, а также на недостоверность данных, содержащихся в нем, за исключением случаев, если соответствующие данные включены в указанный реестр в результате неправомерных действий третьих лиц или иным путем помимо воли юридического лица. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nЮридическое лицо обязано возместить убытки, причиненные другим участникам гражданского оборота вследствие непредставления, несвоевременного представления или представления недостоверных данных о нем в единый государственный реестр юридических лиц.\n\n3. До государственной регистрации юридического лица, изменений его устава или до включения иных данных, не связанных с изменениями устава, в единый государственный реестр юридических лиц уполномоченный государственный орган обязан провести в порядке и в срок, к\n\nоторые предусмотрены законом, проверку достоверности данных, включаемых в указанный реестр.\n\n4. В случаях и в порядке, которые предусмотрены законом о государственной регистрации юридических лиц, уполномоченный государственный орган обязан заблаговременно сообщить заинтересованным лицам о предстоящей государственной регистрации изменений устава юридического лица и о предстоящем включении данных в единый государственный реестр юридических лиц.\n\nЗаинтересованные лица вправе направить в уполномоченный государственный орган возражения относительно предстоящей государственной регистрации изменений устава юридического лица или предстоящего включения данных в единый государственный реестр юридических лиц в порядке, предусмотренном законом о государственной регистрации юридических лиц. Уполномоченный государственный орган обязан рассмотреть эти возражения и принять соответствующее решение в порядке и в срок, которые предусмотрены законом о государственной регистрации юридических лиц.\n\n5. Отказ в государственной регистрации юридического лица, а также во включении данных о нем в единый государственный реестр юридических лиц допускается только в случаях, предусмотренных законом о государственной регистрации юридических лиц.\n\nОтказ в государственной регистрации юридического лица и уклонение от такой регистрации могут быть оспорены в суде.\n\n6. Государственная регистрация юридического лица может быть признана судом недействительной в связи с допущенными при его создании грубыми нарушениями закона, если эти нарушения носят неустранимый характер.\n\nВключение в единый государственный реестр юридических лиц данных о юридическом лице может быть оспорено в суде, если такие данные недостоверны или включены в указанный реестр с нарушением закона.\n\n7. Убытки, причиненные незаконным отказом в государственной регистрации юридического лица, уклонением от государственной регистрации, включением в единый государственный реестр юридических лиц недостоверных данных о юридическом лице либо нарушением порядка государственной регистрации, предусмотренного законом о государственной регистрации юридических лиц, по вине уполномоченного государственного органа, подлежат возмещению за счет казны Российской Федерации.\n\n8. Юридическое лицо считается созданным, а данные о юридическом лице считаются включенными в единый государственный реестр юридических лиц со дня внесения соответствующей записи в этот реестр.\n\n(Статья в редакции Федерального закона от 28.06.2013 № 134-ФЗ)","article_title":"Статья 51. Государственная регистрация юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5f2491d6151385452a5fb96d5d1f84160c3c55267d75eeb24b55519fc530f50"},{"code_id":"GK_RF","article_number":"52","version_date":"1994-11-30","article_text":"Хозяйственное товарищество действует на основании учредительного договора, который заключается его учредителями (участниками) и к которому применяются правила настоящего Кодекса об уставе юридического лица.\n\nГосударственная корпорация действует на основании федерального закона о такой государственной корпорации. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 236-ФЗ)\n\nТиповой устав, утвержденный уполномоченным государственным органом, не содержит сведений о наименовании, фирменном наименовании, месте нахождения и размере уставного капитала юридического лица. Такие сведения указываются в едином государственном реестре юридических лиц.\n\n(Пункт в редакции Федерального закона от 29.06.2015 № 209-ФЗ)\n\nВо внутреннем регламенте и в иных внутренних документах юридического лица могут содержаться положения, не противоречащие учредительному документу юридического лица.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 52. Учредительные документы юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a53c135f4a1e47cbc1b6a61cc1014dcacc4c43571b07cc198e682a9a8349c05"},{"code_id":"GK_RF","article_number":"53","version_date":"1994-11-30","article_text":"Порядок образования и компетенция органов юридического лица определяются настоящим Кодексом, другим законом и учредительным документом, если иное не предусмотрено настоящим Кодексом или другим законом. (В редакции Федерального закона от 25.02.2022 № 20-ФЗ)\n\nУчредительным документом может быть предусмотрено, что полномочия выступать от имени юридического лица предоставлены нескольким лицам, действующим совместно или независимо друг от друга. Сведения об этом подлежат включению в единый государственный реестр юридических лиц.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 53. Органы юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdccf7b609b149cab08a599e622528e93ad67de5a4135e2299a77e9b84c1f520"},{"code_id":"GK_RF","article_number":"53.1","version_date":"1994-11-30","article_text":"1. Лицо, которое в силу закона, иного правового акта или учредительного документа юридического лица уполномочено выступать от его имени (пункт 3 статьи 53), обязано возместить по требованию юридического лица, его учредителей (участников), выступающих в интересах юридического лица, убытки, причиненные по его вине юридическому лицу.\n\nЛицо, которое в силу закона, иного правового акта или учредительного документа юридического лица уполномочено выступать от его имени, несет ответственность, если будет доказано, что при осуществлении своих прав и исполнении своих обязанностей оно действовало недобросовестно или неразумно, в том числе если его действия (бездействие) не соответствовали обычным условиям гражданского оборота или обычному предпринимательскому риску.\n\n2. Ответственность, предусмотренную пунктом 1 настоящей статьи, несут также члены коллегиальных органов юридического лица, за исключением тех из них, кто голосовал против решения, которое повлекло причинение юридическому лицу убытков, или, действуя добросовестно, не принимал участия в голосовании.\n\n3. Лицо, имеющее фактическую возможность определять действия юридического лица, в том числе возможность давать указания лицам, названным в пунктах 1 и 2 настоящей статьи, обязано действовать в интересах юридического лица разумно и добросовестно и несет ответственность за убытки, причиненные по его вине юридическому лицу.\n\n4. В случае совместного причинения убытков юридическому лицу лица, указанные в пунктах 1 - 3 настоящей статьи, обязаны возместить убытки солидарно.\n\n5. Соглашение об устранении или ограничении ответственности лиц, указанных в пунктах 1 и 2 настоящей статьи, за совершение недобросовестных действий, а в публичном обществе за совершение недобросовестных и неразумных действий (пункт 3 статьи 53) ничтожно.\n\nСоглашение об устранении или ограничении ответственности лица, указанного в пункте 3 настоящей статьи, ничтожно.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 53.1. Ответственность лица, уполномоченного выступать от имени юридического лица, членов коллегиальных органов юридического лица и лиц, определяющих действия юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5af03af497a7f8d539f24973b49eadabef71d83140efeffdf4f9c9c7a50ac22b"},{"code_id":"GK_RF","article_number":"53.2","version_date":"1994-11-30","article_text":"В случаях, если настоящий Кодекс или другой закон ставит наступление правовых последствий в зависимость от наличия между лицами отношений связанности (аффилированности), наличие или отсутствие таких отношений определяется в соответствии с законом.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 53.2. Аффилированность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"789cd55b607c4df68ddc04635eaf8843acd3f952b3d4e2fd615e38eb116dc5f6"},{"code_id":"GK_RF","article_number":"54","version_date":"1994-11-30","article_text":"Включение в наименование юридического лица официального наименования Российская Федерация или Россия, а также слов, производных от этого наименования, допускается в случаях, предусмотренных законом, указами Президента Российской Федерации или актами Правительства Российской Федерации, либо по разрешению, выданному в порядке, установленном Правительством Российской Федерации.\n\nПолные или сокращенные наименования федеральных органов государственной власти не могут использоваться в наименованиях юридических лиц, за исключением случаев, предусмотренных законом, указами Президента Российской Федерации или актами Правительства Российской Федерации.\n\nНормативными правовыми актами субъектов Российской Федерации может быть установлен порядок использования в наименованиях юридических лиц официального наименования субъектов Российской Федерации.\n\nЮридическое лицо несет риск последствий неполучения юридически значимых сообщений (статья 1651), доставленных по адресу, указанному в едином государственном реестре юридических лиц, а также риск отсутствия по указанному адресу своего органа или представителя. Сообщения, доставленные по адресу, указанному в едином государственном реестре юридических лиц, считаются полученными юридическим лицом, даже если оно не находится по указанному адресу.\n\nПри наличии у иностранного юридического лица представителя на территории Российской Федерации сообщения, доставленные по адресу такого представителя, считаются полученными иностранным юридическим лицом.\n\nТребования к фирменному наименованию устанавливаются настоящим Кодексом и другими законами. Права на фирменное наименование определяются в соответствии с правилами раздела VII настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 54. Наименование, место нахождения и адрес юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8826419fb662f50ebc1a822d8c821a3a5d42b8ec22da8ee6e1d3ed81c213d869"},{"code_id":"GK_RF","article_number":"55","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Представительством является обособленное подразделение юридического лица, расположенное вне места его нахождения, которое представляет интересы юридического лица и осуществляет их защиту.\n\n2. Филиалом является обособленное подразделение юридического лица, расположенное вне места его нахождения и осуществляющее все его функции или их часть, в том числе функции представительства.\n\n3. Представительства и филиалы не являются юридическими лицами. Они наделяются имуществом создавшим их юридическим лицом и действуют на основании утвержденных им положений.\n\nРуководители представительств и филиалов назначаются юридическим лицом и действуют на основании его доверенности.\n\nПредставительства и филиалы должны быть указаны в едином государственном реестре юридических лиц. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 55. Представительства и филиалы юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4778e42f66052ef0db4e54710b17f4c4004ab2d28386f128be9a9bbec636e3d"},{"code_id":"GK_RF","article_number":"56","version_date":"1994-11-30","article_text":"1. Юридическое лицо отвечает по своим обязательствам всем принадлежащим ему имуществом.\n\nОсобенности ответственности казенного предприятия и учреждения по своим обязательствам определяются правилами абзаца третьего пункта 6 статьи 113, пункта 3 статьи 12321, пунктов 3 - 6 статьи 12322 и пункта 2 статьи 12323 настоящего Кодекса. Особенности ответственности религиозной организации определяются правилами пункта 2 статьи 12328 настоящего Кодекса.\n\n2. Учредитель (участник) юридического лица или собственник его имущества не отвечает по обязательствам юридического лица, а юридическое лицо не отвечает по обязательствам учредителя (участника) или собственника, за исключением случаев, предусмотренных настоящим Кодексом или другим законом.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 56. Ответственность юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2537a9f46e6a89a59d562e246ca27565983acc184231744f6dd282ee6d40b1d"}]$law7d0027$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
